contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOwner, bool impersonate) public payable {
        address beforeOwner = c.owner();

        bool reverted;
        if (impersonate && newOwner != address(this)) {
            // Reassign ownership to a different address so that subsequent calls
            // are made by a non-owner (the test contract), triggering onlyOwner.
            c.setOwner(newOwner);
            // Also include a second setOwner call with a different target to make
            // sure the call that finally reverts is indeed the deciding call.
            (bool ok, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", address(0xdead)));
            reverted = !ok;
            // The previous line drives a non-owner call and observes revert.
            // But we must also test the successful path in the same run.
            // To do that, in this branch we do not use the successful setOwner as the
            // deciding call; instead we restore ownership and then perform the
            // successful path below.
            // Restore ownership to this test contract.
            c.setOwner(address(this));
            c.setOwner(newOwner);
            reverted = false;
        } else {
            // Happy path: test contract is the owner, call setOwner with the
            // argument.  This is the deciding call.
            try c.setOwner(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        address afterOwner = c.owner();

        assert(
            (reverted && afterOwner == beforeOwner) ||
            (!reverted && afterOwner == newOwner && afterOwner != beforeOwner || afterOwner == newOwner && beforeOwner == newOwner)
        );
    }

    receive() external payable {}
}

